import taraweeh from '@/data/taraweehPath.json';
import juzAmma from '@/data/juzAmmaPath.json';

// The two Ramadan paths, generated by scripts/build-ramadan-paths.mjs. Both are free, so (unlike the
// Salah path) the data can be read straight into pages.

export type RootCard = {
  root: string; letters: string; meaning: string; quranCount: number;
  words: { ar: string; en: string | null; ref: string }[];
  inJuz?: number; inJuzAmma?: number;
};
type Place = { surah: number; ayah: number; surahName: string };
export type Night = { night: number; juz: number; start: Place; end: Place; roots: RootCard[]; pctJuz: number; pctQuran: number };
export type AmmaDay = { day: number; title: string; roots: RootCard[]; newlyFollowed: { number: number; name: string }[]; pctJuzAmma: number };

export const TARAWEEH = taraweeh as unknown as { perNight: number; roots: number; nights: Night[] };
export const JUZ_AMMA = juzAmma as unknown as {
  perDay: number; roots: number; totalRoots: number; surahs: { number: number; name: string; pctEnd: number }[]; days: AmmaDay[];
};

export const nightTitle = (n: Night) => `Juz ${n.juz}: from ${n.start.surahName} ${n.start.surah}:${n.start.ayah}`;
